import RNA, itertools, random
target = ".....((.((..(((((.(((....)))(((....)))))).....((((((....)))(((....))).)))))..)).))....................."

# The structure has 4 internal hairpins each (((....))) and outer scaffolding.
# Let's do a constrained random search: initialize structured, then random mutations + accept if bp_dist decreases or equal.
pairs_set = set()
stack=[]
for i,c in enumerate(target):
    if c=='(':stack.append(i)
    elif c==')':
        j=stack.pop(); pairs_set.add((j,i))
        pairs_set.add((i,j))

def bp_dist(s):
    st=[]; p=set()
    for i,c in enumerate(s):
        if c=='(':st.append(i)
        elif c==')':
            j=st.pop(); p.add((j,i))
    return len(p ^ {x for x in pairs_set if x[0]<x[1]})

def init_seq():
    seq=list('A'*len(target))
    # GC all pairs
    for (i,j) in pairs_set:
        if i<j:
            seq[i]='G'; seq[j]='C'
    # GAAA loops at the 4 internal hairpin loops
    for start in [21,31,52,62]:
        for k,m in enumerate("GAAA"):
            seq[start+k]=m
    return ''.join(seq)

def fold(seq):
    fc=RNA.fold_compound(seq)
    ss,mfe=fc.mfe()
    return ss,mfe

best=None; bestd=999
random.seed(1)
cur=init_seq()
curss,curmfe=fold(cur)
# proper distance
def dist(s1):
    st=[];p=set()
    for i,c in enumerate(s1):
        if c=='(':st.append(i)
        elif c==')':
            j=st.pop();p.add((j,i))
    return len(p ^ {x for x in pairs_set if x[0]<x[1]})

curd=dist(curss)
best=cur; bestd=curd
print("init", curd, curss)

for it in range(200000):
    # mutate a random position among paired or loop positions
    pos=random.randrange(len(cur))
    bases=['A','C','G','U']
    nb=random.choice([b for b in bases if b!=cur[pos]])
    cand=cur[:pos]+nb+cur[pos+1:]
    css,cmfe=fold(cand)
    cd=dist(css)
    if cd<curd or (cd==curd and random.random()<0.3):
        cur=cand; curss=css; curd=cd
        if cd<bestd:
            best=cand; bestd=cd
            if cd==0:
                print("SOLVED", it, cand)
                break
    if it%20000==0:
        print(it, bestd, best)

print("FINAL best d=",bestd)
print(best)
